import{B as e,et as t,mt as n,tt as r}from"./chunks/framework.CxxritPY.js";var i=JSON.parse(`{"title":"AI가 버그라고 단언했다.","description":"AI가 맥락 없이 결함을 단언하거나 테스트 조건을 바꿔 통과시킬 때 생기는 검증의 공백을 짚어본다.","frontmatter":{"title":"AI가 버그라고 단언했다.","date":"2026-10-19T07:00+09:00","description":"AI가 맥락 없이 결함을 단언하거나 테스트 조건을 바꿔 통과시킬 때 생기는 검증의 공백을 짚어본다.","tags":["AI","테스트","코드 리뷰"]},"headers":[],"relativePath":"posts/ai-testing.md","filePath":"posts/ai-testing.md","lastUpdated":1793438293000}`),a={name:`posts/ai-testing.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="ai가-버그라고-단언했다" tabindex="-1">AI가 버그라고 단언했다. <a class="header-anchor" href="#ai가-버그라고-단언했다" aria-label="Permalink to “AI가 버그라고 단언했다.”">​</a></h1><p><a href="https://claude.dev/blog/solving-code-review-at-anthropic/" target="_blank" rel="noreferrer">Claude Code 팀의 코드 리뷰 방식</a>을 읽으며 의문이 들었다. AI가 서비스 기능을 분석하고, 결함을 찾아 보고하고, 작업 결과까지 테스트한다면 검증의 기준은 누가 지켜야 할까.</p><h2 id="기능-분석과-결함의-단언" tabindex="-1">기능 분석과 결함의 단언 <a class="header-anchor" href="#기능-분석과-결함의-단언" aria-label="Permalink to “기능 분석과 결함의 단언”">​</a></h2><p>최근 회사 제품에 새로 추가된 기능을 직접 써보고, 문제로 보이는 지점을 분석해 버그가 맞으면 보고해달라고 Claude에 요청했다. Claude는 결함이라며 오류를 단언했고, 몇 번을 다시 물어도 같은 판단을 고수했다.</p><p>해당 기능을 구현한 개발자와 함께 확인해보니 버그가 아니라 의도된 동작이었다. <strong>도메인 맥락을 모른 채</strong> 겉보기 동작만 보고 추정한 결과였다. 기능을 아는 사람이 개입하고 나서야 오판을 바로잡을 수 있었다.</p><div class="info custom-block"><p class="custom-block-title">반복이 근거가 되지는 않아요</p><p>여러 번 다시 물어도 똑같은 오판이 돌아왔어요. 확신에 찬 반복이 검증을 대신할 수는 없어요.</p></div><h2 id="쏟아지는-버그-보고와-검증의-병목" tabindex="-1">쏟아지는 버그 보고와 검증의 병목 <a class="header-anchor" href="#쏟아지는-버그-보고와-검증의-병목" aria-label="Permalink to “쏟아지는 버그 보고와 검증의 병목”">​</a></h2><p>이런 오판과 단언은 개인의 경험에 그치지 않는다. 많은 기업과 오픈소스 프로젝트에서도 AI가 쏟아내는 결함 제보가 끊임없이 등록되고 있다.</p><p>최근 <a href="https://news.hada.io/topic?id=35488" target="_blank" rel="noreferrer">PostgreSQL 19의 출시 연기</a>에서도 AI의 결함 보고가 쏟아지며 검증이 병목이 됐다. 나처럼 AI의 판단을 반박하기 어려워 &#39;일단 올려보자&#39;고 등록한 이슈까지, 실제 결함인지 가려내는 부담은 메인테이너에게 돌아간다.</p><p>AI의 판단에서 무엇이 잘못됐는지 짚어내지 못하면, &#39;그렇구나&#39; 하고 사실로 받아들이게 될 수 있다. 판단을 AI에 맡기는 <strong><a href="https://news.hada.io/topic?id=35230" target="_blank" rel="noreferrer">인지적 외주화</a></strong> 가 근거를 확인하지 않는 맹신으로 이어질 수 있는 것이다.</p><div class="info custom-block"><p class="custom-block-title">지적과 검증의 속도 차이</p><p>결함을 지적하기는 쉬워졌지만, 진짜 결함인지 재현하고 가려내는 일은 결국 사람의 몫이에요.</p></div><h2 id="개선을-맡기고-화면만-확인한다" tabindex="-1">개선을 맡기고 화면만 확인한다 <a class="header-anchor" href="#개선을-맡기고-화면만-확인한다" aria-label="Permalink to “개선을 맡기고 화면만 확인한다”">​</a></h2><p>판단을 AI에 맡기는 흐름은 버그 보고에만 그치지 않는다. <a href="https://news.hada.io/topic?id=35541" target="_blank" rel="noreferrer">AI 에이전트와 달라진 개발 업무에 관한 글</a>은 코드를 직접 검토하기보다 결과물의 QA와 제약 조건을 먼저 챙기는 쪽으로 바뀐 일상을 다룬다. 사내 도구를 관리하는 내 업무도 비슷하게 흘러간다.</p><p>AI는 도구의 업무 맥락을 충분히 이해하지 못한 채 스스로 개선점을 찾아 고치고 배포한다. 그러면 나는 QA 입장에서 화면을 눌러보며 평소 쓰던 기능이 여전히 잘 동작하는지 확인하게 된다. 기존 기능이 유지된다는 사실만으로는 방금 배포한 변경이 업무에 정말 필요한 개선이었는지 알 수 없다.</p><div class="info custom-block"><p class="custom-block-title">화면이 잘 돌아가는지보다 무엇을 왜 바꿨는지가 더 중요하다</p><p>사내 도구는 개선 목표가 뚜렷하지 않아 <a href="https://news.hada.io/topic?id=29639" target="_blank" rel="noreferrer">Codex의 Goals</a> 대신 <a href="https://learn.chatgpt.com/docs/changelog#codex-2026-10-09-composer-predictions" target="_blank" rel="noreferrer">다음 요청 제안 기능</a>을 주로 써요. 탭 키 하나로 수정과 배포가 빠르게 이어지지만, 그만큼 변경 이유를 따져보는 과정은 건너뛰기 쉬워요.</p></div><h2 id="테스트를-통과시키려고-검증-조건을-바꿨다" tabindex="-1">테스트를 통과시키려고 검증 조건을 바꿨다 <a class="header-anchor" href="#테스트를-통과시키려고-검증-조건을-바꿨다" aria-label="Permalink to “테스트를 통과시키려고 검증 조건을 바꿨다”">​</a></h2><p>AI는 결함을 지적할 때 근거 없는 추정을 확신하기도 하고, 작업 결과를 검증할 때는 <mark>테스트 조건을 바꿔 실제 결함을 놓치기도</mark> 한다. <a href="https://techblog.yogiyo.co.kr/product-engineer%EC%9D%98-%EB%B3%91%EB%AA%A9-%EC%BD%94%EB%93%9C%EC%97%90%EC%84%9C-%EA%B2%80%EC%A6%9D%EC%9C%BC%EB%A1%9C-17b3db81121d" target="_blank" rel="noreferrer">요기요 사례</a>에서는 동시성 테스트를 순차 실행으로 바꾸자 테스트가 통과했고, 원래대로 복원한 뒤에야 버그가 드러났다.</p><p>AI의 결함 보고도, 테스트 통과 보고도 그대로 믿기 어려운 이유다.</p><h2 id="통과했지만-다른-곳을-확인했다" tabindex="-1">통과했지만 다른 곳을 확인했다 <a class="header-anchor" href="#통과했지만-다른-곳을-확인했다" aria-label="Permalink to “통과했지만 다른 곳을 확인했다”">​</a></h2><p><a href="https://techblog.lycorp.co.jp/ko/ai-e2e-test-automation" target="_blank" rel="noreferrer">LINE Plus의 E2E 테스트 자동화 사례</a>에서는 광고 영역 대신 공지 영역을 검사하거나, 여섯 항목 중 하나만 확인하고도 테스트가 통과했다. 실행은 성공했지만 <strong>의도한 검증은 빠져 있었다.</strong> 이후 기대 결과와 검증문을 연결하고, 모호한 조건은 사람에게 확인하도록 바꿨다.</p><p>실제 검증 대상을 스크린샷으로 남겨 사람이 직접 확인할 수 있도록 한 것 같다.</p><h2 id="최선을-다해-이해하려고-하자" tabindex="-1">최선을 다해 이해하려고 하자 <a class="header-anchor" href="#최선을-다해-이해하려고-하자" aria-label="Permalink to “최선을 다해 이해하려고 하자”">​</a></h2><p>서로 다른 모델로 교차 검증을 수행해도 판단이 갈릴 수 있다. 반대로 같은 추정을 바탕으로 모두 잘못된 판단을 내릴 수도 있다. 여러 모델이 동의했다는 사실만으로 검증이 끝났다고 보기는 어렵다.</p><p><a href="https://news.hada.io/topic?id=35504" target="_blank" rel="noreferrer">리누스 토르발스가 강조한 것</a>은 <mark>자신이 하는 일을 이해해야 한다</mark> 는 것이다. AI가 결함이라고 판단한 근거, 코드를 바꾼 이유, 테스트가 실제로 확인한 내용을 이해하려는 노력은 여전히 필요하다.</p><h2 id="참고-자료" tabindex="-1">참고 자료 <a class="header-anchor" href="#참고-자료" aria-label="Permalink to “참고 자료”">​</a></h2><ul><li><a href="https://claude.dev/blog/solving-code-review-at-anthropic/" target="_blank" rel="noreferrer">Claude Code 팀의 코드 리뷰 방식 (Anthropic)</a></li><li><a href="https://news.hada.io/topic?id=35488" target="_blank" rel="noreferrer">Postgres 19 출시 지연, AI 리뷰가 사람이 고칠 수 있는 양보다 많은 버그를 발견 (GeekNews)</a></li><li><a href="https://news.hada.io/topic?id=35541" target="_blank" rel="noreferrer">예전의 내 일은 이제 멀게 느껴진다: AI 에이전트와 달라진 개발 업무 (GeekNews)</a></li><li><a href="https://techblog.yogiyo.co.kr/product-engineer%EC%9D%98-%EB%B3%91%EB%AA%A9-%EC%BD%94%EB%93%9C%EC%97%90%EC%84%9C-%EA%B2%80%EC%A6%9D%EC%9C%BC%EB%A1%9C-17b3db81121d" target="_blank" rel="noreferrer">Product Engineer의 병목: 코드에서 검증으로 (요기요 기술블로그)</a></li><li><a href="https://techblog.lycorp.co.jp/ko/ai-e2e-test-automation" target="_blank" rel="noreferrer">AI로 E2E 회귀 테스트 자동화하기: ‘딸깍’을 파이프라인으로 바꾸기까지 (LY Corporation)</a></li><li><a href="https://news.hada.io/topic?id=35504" target="_blank" rel="noreferrer">Linus Torvalds “AI 사용을 금지하지 않겠다. 자신이 하는 일을 이해해야 한다” (GeekNews)</a></li></ul>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};